import{_ as s,o as e,c as a,a2 as r}from"./chunks/framework.Boholvbs.js";const E=JSON.parse('{"title":"xsync-exit(7)","description":"Inspect final status, retained partials, and original diagnostics.","frontmatter":{"title":"xsync-exit(7)","description":"Inspect final status, retained partials, and original diagnostics.","manual":"xsync-exit(7)","manualName":"Exit status & errors","sectionNumber":"7"},"headers":[],"relativePath":"exit-status.md","filePath":"exit-status.md"}'),n={name:"exit-status.md"};function o(i,t,l,c,d,p){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="xsync-exit-7" tabindex="-1">xsync-exit(7) <a class="header-anchor" href="#xsync-exit-7" aria-label="Permalink to &quot;xsync-exit(7)&quot;">​</a></h1><div class="manual-deck"><strong>Exit status &amp; errors</strong><p>Inspect final status, retained partials, and original diagnostics.</p></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION {#description}&quot;">​</a></h2><p>A final exit status describes the process outcome. Transfer errors include a bounded summary of the first ten diagnostics, grouped by kind, on stderr. Quiet mode keeps errors visible.</p><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS {#exit-status}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Code</th><th scope="col">Meaning</th></tr></thead><tbody><tr><td>0</td><td>Successful operation</td></tr><tr><td>1</td><td>Syntax or usage error</td></tr><tr><td>2</td><td>Protocol incompatibility</td></tr><tr><td>3</td><td>Input/output selection error</td></tr><tr><td>4</td><td>Requested action unsupported</td></tr><tr><td>5</td><td>Failure starting the client/server protocol</td></tr><tr><td>11</td><td>File I/O error, including fatal disk-full errors</td></tr><tr><td>12</td><td>Protocol data-stream error</td></tr><tr><td>13</td><td>Diagnostic/stdout write failure, including a closed output pipe</td></tr><tr><td>14</td><td>Interprocess communication error</td></tr><tr><td>20</td><td>SIGINT, SIGTERM, or SIGHUP</td></tr><tr><td>23</td><td>Some files or attributes were not transferred</td></tr><tr><td>24</td><td>Source files vanished before transfer</td></tr><tr><td>25</td><td>Deletion limit exceeded</td></tr><tr><td>30</td><td>Remote idle I/O timeout</td></tr></tbody></table></div><h2 id="missing-source" tabindex="-1">MISSING SOURCE <a class="header-anchor" href="#missing-source" aria-label="Permalink to &quot;MISSING SOURCE {#missing-source}&quot;">​</a></h2><div class="example-caption">Command from the actual error recording</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xsync </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> ./missing-source/</span><span style="color:#DEDEDE;"> ./unused-backup/</span></span></code></pre></div><div class="captured-doc-output"><span class="micro">ACTUAL XSYNC DIAGNOSTIC / EXIT 23</span><pre><code id="actual-error-output">xsync: link_stat &quot;./missing-source/&quot; failed: No such file or directory (2)
xsync: error summary: 1 error (showing first 1)
  partial transfer (code 23): 1 error
    link_stat &quot;./missing-source/&quot; failed: No such file or directory (2)
xsync error: some files/attrs were not transferred (see previous errors) (code 23)</code></pre></div><h2 id="interruption" tabindex="-1">INTERRUPTION AND RETRY <a class="header-anchor" href="#interruption" aria-label="Permalink to &quot;INTERRUPTION AND RETRY {#interruption}&quot;">​</a></h2><p>Ctrl-C interrupts a run with exit code 20. With <code>-P</code>, completed contiguous partial data can be retained. Rerun the same transfer to verify and reuse matching prefixes.</p><div class="example-caption">Retry a partial transfer</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xsync </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>A completed-byte prefix can be reused only when it matches the source. Transfers do not invoke fallback after an active copy has failed.</p><h2 id="scripts" tabindex="-1">SCRIPT EXAMPLE <a class="header-anchor" href="#scripts" aria-label="Permalink to &quot;SCRIPT EXAMPLE {#scripts}&quot;">​</a></h2><div class="example-caption">Preserve the command’s original exit status</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">if xsync </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --no-progress</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;">; then</span></span>
<span class="line"><span style="color:#DEDEDE;">  echo </span><span style="color:#DEDEDE;">&quot;transfer completed&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">else</span></span>
<span class="line"><span style="color:#DEDEDE;">  status=$?</span></span>
<span class="line"><span style="color:#DEDEDE;">  echo </span><span style="color:#DEDEDE;">&quot;xsync failed with code $status&quot;</span><span style="color:#DEDEDE;"> &gt;&amp;2</span></span>
<span class="line"><span style="color:#DEDEDE;">  exit </span><span style="color:#DEDEDE;">&quot;$status&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">fi</span></span></code></pre></div><p>An exit-23 result may include successful files and failed files in the same run. Inspect the diagnostics rather than assuming the entire destination was rolled back.</p>`,19)])])}const D=s(n,[["render",o]]);export{E as __pageData,D as default};
